head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > readOnly]<br/>특정 Body Cell 이 아닌 Body Column 의 읽기전용(readonly) 상태를 설정합니다.",
    "validation" : [
        "false 설정 시, Body Column 의 읽기전용(readonly) 상태를 해제합니다.",
        "미설정 시, readOnlyPriority 속성에 따라 상위 모듈의 읽기전용(readonly) 상태가 적용됩니다.",
        "readOnly 해제(편집 가능) 상태에서 Cell 을 더블클릭 시 Edit Mode 로 진입합니다.",
        "readOnly 해제 상태의 Cell 에는 readOnlyClass 클래스가 적용되지 않습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 편집 가능한 GridView (gBody 4 Column, editType=text), 데이터 4건
//  - col2 = readOnly="false" (명시 해제, 생성 시 고정) / col3 = readOnly 미설정 (상위 GridView readonly=false 상속) : con 셀렉트박스 없음
//    · col2 readOnly="false" -> 읽기전용 해제 (편집 가능, readOnlyClass 미적용)
//    · col3 미설정(readOnly 속성 제외) -> 상위 모듈(GridView readonly=false 기본) 적용 -> 편집 가능
//  - col2 에는 readOnlyClass="tc_readonly_target" 지정 -> readOnly 해제 상태이므로 셀에 해당 클래스가 적용되지 않음을 확인 (spec 대조)
//  - col1,col4 는 편집 대조군. 상위 GridView 레벨 readOnly 미설정(기본 false)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] col2 의 readOnly = false (명시 해제, 생성 시 고정) / col3 의 readOnly = 미설정 (상위 GridView readonly=false 상속) / 상위 GridView readonly=false / col1,col4 편집 대조\n[절차] col2·col3 셀 더블클릭 -> Edit Mode 진입(편집 가능) 확인\n[확인] readOnly 상태 확인 버튼으로 col2 getColumnReadOnly=false / col3 getColumnReadOnly=\'\'(미설정) / readOnlyClass 미적용 확인"', '', 'label1');

    // dataList 생성 (col1~col4 4컬럼 바인딩)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { col1 : "RowA", col2 : "AAA", col3 : "10", col4 : "TextA" },
        { col1 : "RowB", col2 : "BBB", col3 : "20", col4 : "TextB" },
        { col1 : "RowC", col2 : "CCC", col3 : "30", col4 : "TextC" },
        { col1 : "RowD", col2 : "DDD", col3 : "40", col4 : "TextD" }
    ]);

    // col2 의 readOnly 속성 : false (명시 해제, 생성 시 고정). col3 은 readOnly 속성 미설정(상위 모듈 상속).
    let col2ReadOnlyAttr = ' readOnly="false"';

    // GridView 레벨 readOnly 미설정(기본 false) -> col2 미설정 시 상위 모듈(false)이 적용되어 편집 가능
    let eList = $c.gcm.createEList(["oncellclick", "oncelldblclick", "onkeydown"]);

    // target 생성 (편집 가능 그리드 : gBody Column 에 editType="text")
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + eList + ' dataList="data:dlt_bind" focusMode="cell" checkAllType="false" readOnlyBackgroundColor="#D3D3D3" id="" style="width:440px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="Column readOnly 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="col1(편집)"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column2" value="col2(false)"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column3" value="col3(미설정)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column4" value="col4(편집)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col1" editType="text"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" editType="text" readOnlyClass="tc_readonly_target"' + col2ReadOnlyAttr + '></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col3" editType="text"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col4" editType="text"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// readOnly 상태 확인 버튼
//  - col2(readOnly=false 명시) getColumnReadOnly : false / col3(미설정) getColumnReadOnly : "" (상위 상속)
//  - col2 Cell(0) getCellReadOnly : Cell 단위 readOnly 는 "" 유지 (관측 수단)
//  - col2 Cell(0) readOnlyClass(tc_readonly_target) 적용 여부 : readOnly 해제 상태이므로 미적용(false) (spec 대조)
scwin.btn_checkReadOnly_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let col2ReadOnly = target1.getColumnReadOnly(1);
    bottom.setReturnValue("col2(false 명시) getColumnReadOnly : '" + col2ReadOnly + "'");

    let col3ReadOnly = target1.getColumnReadOnly(2);
    bottom.setReturnValue("col3(미설정) getColumnReadOnly : '" + col3ReadOnly + "'");

    let cellReadOnly = target1.getCellReadOnly(0, 1);
    bottom.setReturnValue("col2 Cell(0) getCellReadOnly : '" + cellReadOnly + "'");

    let cell = document.querySelector("td[id*='target1_cell_0_1']");
    let hasCls = cell ? (cell.className.indexOf("tc_readonly_target") > -1) : false;
    bottom.setReturnValue("col2 Cell(0) readOnlyClass(tc_readonly_target) 적용 : " + hasCls);
}



// 셀 클릭 시 발생
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    wf_body_bottom.getObj("scwin").setReturnValue("oncellclick 발생 : Cell(" + rowIndex + "," + columnIndex + ") columnId=" + columnId);
}



// 셀 더블클릭 시 발생 (readOnly 해제 상태의 셀은 Edit Mode 진입 -> isEditing=true)
scwin.target1_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    let editing = target1.isEditing();
    wf_body_bottom.getObj("scwin").setReturnValue("oncelldblclick 발생 : Cell(" + rowIndex + "," + columnIndex + ") isEditing=" + editing);
}



// 키다운 시 발생
scwin.target1_onkeydown = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("onkeydown 발생 : keyCode=" + (e.keyCode || e.which));
}
